window.Capture=(()=>{
 const limit=1000,records=[],listeners=new Set();let sequence=0;
 function clean(value,depth=0){if(depth>5)return '[truncated]';if(value instanceof Error)return {name:value.name,message:value.message,stack:value.stack};if(Array.isArray(value))return value.slice(0,100).map(v=>clean(v,depth+1));if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).slice(0,100).map(([k,v])=>[k,/token|password|secret|authorization|cookie/i.test(k)?'[redacted]':clean(v,depth+1)]));return typeof value==='string'?value.slice(0,8000):value;}
 function add(entry){const record={id:'log-'+Date.now()+'-'+(++sequence),timestamp:new Date().toISOString(),elapsedSeconds:null,severity:'info',source:'Application',collectionId:null,deviceId:null,eventType:'application.event',message:'',details:{},provenance:'Application',...clean(entry)};records.push(record);if(records.length>limit)records.shift();listeners.forEach(fn=>fn(record));return record;}
 function subscribe(fn){listeners.add(fn);return ()=>listeners.delete(fn);}
 window.addEventListener('error',event=>add({severity:'error',source:'Browser',eventType:'browser.error',message:event.message||'Resource could not load',details:{file:event.filename||event.target?.src||'',line:event.lineno,stack:event.error?.stack}}),true);
 window.addEventListener('unhandledrejection',event=>add({severity:'error',source:'Browser',eventType:'browser.rejection',message:event.reason?.message||String(event.reason),details:{reason:clean(event.reason)}}));
 add({eventType:'application.started',message:'Application session started.'});
 return {add,subscribe,records,limit};
})();

window.Diagnostics=(()=>{
 const {e,icon,button,select}=UI;
 const state={tab:'devices',scope:'all',query:'',severity:'all',source:'all',selected:null,follow:true,cutoff:null,page:0,eventPage:0,returnRoute:'settings',returnFocus:null};
 const pageSize=40;
 const levelIcons={debug:'code',info:'info',warning:'alert',error:'alert'};
 function filtered(){return Capture.records.filter(r=>(state.scope==='all'||r.collectionId===state.scope)&&(state.severity==='all'||r.severity===state.severity)&&(state.source==='all'||r.source===state.source)&&(!state.query||[r.message,r.eventType,r.deviceId,r.source,JSON.stringify(r.details)].join(' ').toLowerCase().includes(state.query.toLowerCase()))&&(!state.cutoff||r.timestamp<=state.cutoff)).reverse();}
 function time(r){return new Date(r.timestamp).toLocaleTimeString([], {hour12:false})+'.'+r.timestamp.slice(20,23);}
 function level(r){return `<span class="log-level level-${e(r.severity)}">${icon(levelIcons[r.severity]||'info')}${e(r.severity)}</span>`;}
 function rows(){
  const list=filtered(),pages=Math.max(1,Math.ceil(list.length/pageSize));state.page=Math.min(state.page,pages-1);
  return `<div class="log-count">${list.length} entries${!state.follow?` · ${Capture.records.filter(r=>r.timestamp>state.cutoff&&(state.scope==='all'||r.collectionId===state.scope)).length} new`:''}</div><div class="table-wrap log-table-wrap"><table class="log-table"><thead><tr><th>Time</th><th>Level</th><th class="log-source-cell">Source</th><th>Message</th></tr></thead><tbody>${list.slice(state.page*pageSize,(state.page+1)*pageSize).map(r=>`<tr class="log-entry ${state.selected===r.id?'selected':''}"><td class="log-time-cell"><time datetime="${e(r.timestamp)}">${time(r)}</time></td><td>${level(r)}</td><td class="log-source-cell"><span>${e(r.source)}</span>${r.deviceId?`<span class="row-subline">${e(Cousins.getDevice(r.deviceId)?.name||r.deviceId)}</span>`:''}</td><td><button class="log-message" data-action="log-select" data-id="${e(r.id)}" aria-expanded="${state.selected===r.id}" aria-controls="details-${e(r.id)}">${icon(state.selected===r.id?'down':'right')}<span>${e(r.message)}</span></button><span class="log-mobile-source">${e(r.source)}</span></td></tr>${state.selected===r.id?`<tr class="log-detail-row" id="details-${e(r.id)}"><td colspan="4"><div class="log-details"><dl><div><dt>Timestamp</dt><dd>${e(r.timestamp)}</dd></div><div><dt>Source</dt><dd>${e(r.source)}${r.deviceId?' · '+e(r.deviceId):''}</dd></div><div><dt>Provenance</dt><dd>${e(r.provenance)}</dd></div><div><dt>Event</dt><dd>${e(r.eventType)}</dd></div>${r.collectionId?`<div><dt>Collection</dt><dd>${e(Cousins.getCollection(r.collectionId)?.name||r.collectionId)}</dd></div>`:''}${r.elapsedSeconds!==null?`<div><dt>Elapsed</dt><dd>${Cousins.duration(r.elapsedSeconds)}</dd></div>`:''}</dl><pre>${e(JSON.stringify(r.details,null,2))}</pre>${button('Copy entry','log-copy',{id:r.id,icon:'copy',quiet:true})}</div></td></tr>`:''}`).join('')||`<tr><td colspan="4"><div class="logs-empty"><strong>${Capture.records.some(r=>state.scope==='all'||r.collectionId===state.scope)?'No matching entries':'No capture entries yet'}</strong><p>New session activity appears here. Adjust filters to show more entries.</p>${button('Reset filters','log-reset',{quiet:true})}</div></td></tr>`}</tbody></table></div>${pages>1?`<div class="log-pagination">${button('Previous','log-prev',{disabled:state.page===0})}<span>${state.page+1} / ${pages}</span>${button('Next','log-next',{disabled:state.page>=pages-1})}</div>`:''}`;
 }
 function filters(){const scopes=[{value:'all',label:'All application'},...Cousins.db.collections.map(c=>({value:c.id,label:c.name}))],sources=['all',...new Set(Capture.records.map(r=>r.source))];return `<div class="log-filters"><label class="field">Scope${select('scope',state.scope,scopes,'data-log-filter="scope"')}</label><label class="field log-search">Search<input type="search" value="${e(state.query)}" placeholder="Message, device or event" data-log-query></label><div class="two-fields"><label class="field">Severity${select('severity',state.severity,['all','debug','info','warning','error'].map(value=>({value,label:value==='all'?'All levels':value[0].toUpperCase()+value.slice(1)})),'data-log-filter="severity"')}</label><label class="field">Source${select('source',state.source,sources.map(value=>({value,label:value==='all'?'All sources':value})),'data-log-filter="source"')}</label></div><div class="actions">${button(state.follow?'Pause following':'Follow latest','log-follow',{icon:state.follow?'pause':'play',quiet:true})}${button('Download','log-download',{icon:'download',quiet:true})}</div><p class="log-retention">Current browser session · Latest ${Capture.limit.toLocaleString()} entries</p></div>`;}
 function logs(){return `${filters()}<div data-log-results>${rows()}</div>`;}
 function devices(run){return `<div class="diagnostic-devices">${Object.entries(run.deviceStates).map(([id,s])=>{const d=Cousins.getDevice(id);return `<article class="diagnostic-device"><header>${icon('device')}<strong>${e(d?.name||id)}</strong></header><dl><div><dt>Connection</dt><dd>${Runtime.status(s.connection)}</dd></div><div><dt>Operation</dt><dd>${e(s.operation)}</dd></div><div><dt>Last command</dt><dd>${Runtime.status(s.command)}</dd></div>${d?`<div><dt>${e(d.parameter)}</dt><dd>${e(s.applied)} ${e(d.unit)} applied${s.draft!==null&&s.draft!==undefined?`<span>${e(s.draft)} ${e(d.unit)} pending</span>`:''}</dd></div>`:''}</dl>${s.connection==='Disconnected'&&run.acquisition!=='Completed'?button('Reconnect','reconnect',{icon:'refresh'}):''}${button('Device logs','device-logs',{id,quiet:true})}</article>`;}).join('')}<p class="field-hint">Failure policy: ${run.policy==='stop'?'Stop all devices':'Continue remaining devices'}.</p>${run.acquisition!=='Completed'?`<details class="simulation"><summary>${icon('sliders')}Simulate a failure</summary><p>Mock connections. No hardware is operated.</p><div class="actions">${button('Disconnect','simulate-disconnect')}${button('Interrupt recording','simulate-storage')}${button('Command timeout','simulate-uncertain')}</div></details>`:''}</div>`;}
 function events(run){const events=[...run.events].sort((a,b)=>(b.elapsedSeconds??0)-(a.elapsedSeconds??0)),pages=Math.max(1,Math.ceil(events.length/pageSize));state.eventPage=Math.min(state.eventPage,pages-1);return `<div class="diagnostic-events">${events.slice(state.eventPage*pageSize,(state.eventPage+1)*pageSize).map(ev=>`<article class="capture-event"><time>${e(ev.elapsedSeconds===undefined?ev.time:Cousins.duration(ev.elapsedSeconds))}</time><div class="od-field"><strong>${e(ev.text)}</strong><span>${e(ev.provenance||'Historical example')}</span>${ev.logId?button('View log','event-log',{id:ev.logId,quiet:true}):''}</div></article>`).join('')||'<p>No collection events yet.</p>'}<div class="log-pagination">${button('Previous','event-prev',{disabled:state.eventPage===0})}<span>${state.eventPage+1} / ${pages}</span>${button('Next','event-next',{disabled:state.eventPage>=pages-1})}</div></div>`;}
 function panel(run){return `<aside class="diagnostics-panel" aria-label="Collection diagnostics"><header><h2>${state.tab==='logs'?'Capture logs':state.tab==='events'?'Events':'Devices'}</h2><div class="actions">${state.tab==='logs'?button('Expand logs','logs-expand',{icon:'external',iconOnly:true}):''}${button('Close diagnostics','diagnostics-close',{icon:'close',iconOnly:true})}</div></header><div class="diagnostic-tabs" role="tablist" aria-label="Diagnostics">${['devices','events','logs'].map(t=>`<button role="tab" data-action="diagnostics-tab" data-id="${t}" aria-selected="${state.tab===t}" class="${state.tab===t?'active':''}">${t==='logs'?'Logs':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="diagnostic-content" role="tabpanel">${state.tab==='logs'?logs():state.tab==='events'?events(run):devices(run)}</div></aside>`;}
 function refresh(){const active=document.activeElement,selected=active?.dataset.action==='log-select'?active.dataset.id:null;const root=document.querySelector('[data-log-results]');if(root)root.innerHTML=rows();if(selected)root?.querySelector(`[data-action="log-select"][data-id="${selected}"]`)?.focus({preventScroll:true});}
 function refreshPanel(){const run=Runtime.active(),host=document.getElementById('runtime-panel-host');if(!run||!host)return;host.innerHTML=state.tab?panel(run):'';document.querySelector('.runtime-workspace')?.classList.toggle('has-diagnostics',!!state.tab);document.querySelectorAll('[data-diagnostics-trigger]').forEach(b=>{b.setAttribute('aria-expanded',String(state.tab===b.dataset.diagnosticsTrigger));b.classList.toggle('selected',state.tab===b.dataset.diagnosticsTrigger);});}
 function open(tab,trigger){state.tab=tab;state.eventPage=0;state.returnFocus=trigger?.dataset.action||'open-logs';const run=Runtime.active();if(run)state.scope=run.id;refreshPanel();document.querySelector('.diagnostics-panel button')?.focus({preventScroll:true});if(innerWidth<1100)document.querySelector('.diagnostics-panel')?.scrollIntoView({block:'start',behavior:'instant'});}
 function close(){state.tab=null;refreshPanel();document.querySelector(`[data-action="${state.returnFocus}"]`)?.focus({preventScroll:true});}
 function renderPage(){return `<div class="page expanded-logs">${UI.header('Capture logs',button('Back','logs-return',{icon:'left',quiet:true}),'<span class="scope-label">Application session</span>')}${logs()}</div>`;}
 function action(action,id,el){if(action==='event-prev'||action==='event-next'){state.eventPage+=action==='event-next'?1:-1;refreshPanel();return true;}if(action==='open-devices'||action==='run-details'){open('devices',el);return true;}if(action==='open-events'){open('events',el);return true;}if(action==='open-logs'){open('logs',el);return true;}if(action==='diagnostics-close'){close();return true;}if(action==='diagnostics-tab'){state.tab=id;refreshPanel();document.querySelector(`[data-action="diagnostics-tab"][data-id="${id}"]`)?.focus();return true;}if(action==='event-log'){state.tab='logs';state.scope=Runtime.active().id;state.query='';state.severity='all';state.source='all';state.follow=true;state.cutoff=null;state.selected=id;state.page=Math.max(0,Math.floor(filtered().findIndex(r=>r.id===id)/pageSize));refreshPanel();document.querySelector('.log-entry.selected')?.scrollIntoView({block:'nearest'});return true;}if(action==='device-logs'){open('logs',el);state.query=id;state.page=0;refreshPanel();return true;}
 if(action==='logs-expand'||action==='application-logs'||action==='collection-logs'){state.returnRoute=App.ui.route;if(action==='application-logs')state.scope='all';if(action==='collection-logs')state.scope=id;App.navigate('logs');return true;}if(action==='logs-return'){App.navigate(state.returnRoute);return true;}
 if(!action.startsWith('log-'))return false;
 if(action==='log-select')state.selected=state.selected===id?null:id;
 if(action==='log-prev')state.page=Math.max(0,state.page-1);
 if(action==='log-next')state.page++;
 if(action==='log-follow'){state.follow=!state.follow;state.cutoff=state.follow?null:new Date().toISOString();state.page=0;const root=document.querySelector('.log-filters');if(root)root.outerHTML=filters();}
 if(action==='log-reset'){state.query='';state.severity='all';state.source='all';state.page=0;document.querySelector('.log-filters').outerHTML=filters();}
 if(action==='log-copy'){const r=Capture.records.find(r=>r.id===id);if(r){const text=JSON.stringify(r,null,2);if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>App.toast('Log entry copied.')).catch(()=>App.toast('Copy is unavailable. Download the filtered logs instead.'));else App.toast('Copy is unavailable. Download the filtered logs instead.');}return true;}
 if(action==='log-download'){const blob=new Blob([filtered().map(r=>JSON.stringify(r)).join('\n')],{type:'application/x-ndjson'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='cousins-capture-logs.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);App.toast('Filtered logs downloaded.');return true;}
 refresh();return true;
 }
 document.addEventListener('input',event=>{if(event.target.matches('[data-log-query]')){state.query=event.target.value;state.page=0;refresh();}});
 document.addEventListener('change',event=>{const key=event.target.dataset.logFilter;if(key){state[key]=event.target.value;state.page=0;refresh();}});
 document.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)&&event.target.matches('.diagnostic-tabs button')){const tabs=['devices','events','logs'],i=tabs.indexOf(state.tab);state.tab=tabs[event.key==='Home'?0:event.key==='End'?2:(i+(event.key==='ArrowRight'?1:2))%3];refreshPanel();document.querySelector(`[data-action="diagnostics-tab"][data-id="${state.tab}"]`)?.focus();event.preventDefault();}if(event.key==='Escape'&&document.querySelector('.diagnostics-panel')){close();event.preventDefault();}});
 Capture.subscribe(()=>{if(state.follow)refresh();else {const count=document.querySelector('.log-count');if(count)count.textContent=filtered().length+' entries · '+Capture.records.filter(r=>r.timestamp>state.cutoff&&(state.scope==='all'||r.collectionId===state.scope)).length+' new';}const source=document.querySelector('[data-log-filter="source"]');if(source){const current=source.value;source.innerHTML=['all',...new Set(Capture.records.map(r=>r.source))].map(s=>`<option value="${e(s)}">${s==='all'?'All sources':e(s)}</option>`).join('');source.value=current;}});
 state.tab=null;
 return {state,panel,open,close,action,renderPage,refreshPanel,refresh};
})();
